   153	        switch (iouType) {
   154	            case CONST.IOU.TYPE.REQUEST:
   155	                Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CONFIRMATION.getRoute(CONST.IOU.ACTION.CREATE, CONST.IOU.TYPE.SUBMIT, transactionID, reportID));
   156	                break;
   157	            case CONST.IOU.TYPE.SEND:
   158	                Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CONFIRMATION.getRoute(CONST.IOU.ACTION.CREATE, CONST.IOU.TYPE.PAY, transactionID, reportID));
   159	                break;
   160	            default:
   161	                Navigation.navigate(ROUTES.MONEY_REQUEST_STEP_CONFIRMATION.getRoute(CONST.IOU.ACTION.CREATE, iouType, transactionID, reportID));
   162	        }
   163	    };
   164	
   165	    const navigateToNextPage = ({amount, paymentMethod}: AmountParams) => {
   166	        isSaveButtonPressed.current = true;
   167	        const amountInSmallestCurrencyUnits = CurrencyUtils.convertToBackendAmount(Number.parseFloat(amount));
   168	
   169	        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   170	        IOU.setMoneyRequestAmount(transactionID, amountInSmallestCurrencyUnits, currency || CONST.CURRENCY.USD, shouldKeepUserInput);
   171	
   172	        // Initially when we're creating money request, we do not know the participant and hence if the request is with workspace with tax tracking enabled
   173	        // So, we reset the taxAmount here and calculate it in the hook in MoneyRequestConfirmationList component
   174	        IOU.setMoneyRequestTaxAmount(transactionID, null);
   175	
   176	        if (backTo) {
   177	            Navigation.goBack(backTo);
   178	            return;
   179	        }
   180	
   181	        // If a reportID exists in the report object, it's because the user started this flow from using the + button in the composer
   182	        // inside a report. In this case, the participants can be automatically assigned from the report and the user can skip the participants step and go straight
   183	        // to the confirm step.
   184	        if (report?.reportID && !ReportUtils.isArchivedRoom(report, reportNameValuePairs)) {
   185	            const selectedParticipants = IOU.setMoneyRequestParticipantsFromReport(transactionID, report);
   186	            const participants = selectedParticipants.map((participant) => {
   187	                const participantAccountID = participant?.accountID ?? -1;
   188	                return participantAccountID ? OptionsListUtils.getParticipantsOption(participant, personalDetails) : OptionsListUtils.getReportOption(participant);
   189	            });
   190	            const backendAmount = CurrencyUtils.convertToBackendAmount(Number.parseFloat(amount));
   191	
   192	            if (shouldSkipConfirmation) {
   193	                // Only skip confirmation when the split is not configurable, for now Smartscanned splits cannot be configured
   194	                if (iouType === CONST.IOU.TYPE.SPLIT && transaction?.iouRequestType === CONST.IOU.REQUEST_TYPE.SCAN) {
   195	                    IOU.splitBill({
   196	                        participants,
   197	                        currentUserLogin: currentUserPersonalDetails.login ?? '',
   198	                        currentUserAccountID: currentUserPersonalDetails.accountID,
   199	                        amount: backendAmount,
   200	                        comment: '',
   201	                        currency,
   202	                        merchant: CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT,
   203	                        tag: '',
   204	                        category: '',
   205	                        created: transaction?.created ?? '',
   206	                        billable: false,
   207	                        iouRequestType: CONST.IOU.REQUEST_TYPE.MANUAL,
   208	                        existingSplitChatReportID: report?.reportID,
   209	                    });
   210	                    return;
   211	                }
   212	
   213	                if (iouType === CONST.IOU.TYPE.PAY || iouType === CONST.IOU.TYPE.SEND) {
   214	                    if (paymentMethod && paymentMethod === CONST.IOU.PAYMENT_TYPE.EXPENSIFY) {
   215	                        IOU.sendMoneyWithWallet(report, backendAmount, currency, '', currentUserPersonalDetails.accountID, participants[0]);
   216	                        return;
   217	                    }
   218	
   219	                    IOU.sendMoneyElsewhere(report, backendAmount, currency, '', currentUserPersonalDetails.accountID, participants[0]);
   220	                    return;
   221	                }
   222	                if (iouType === CONST.IOU.TYPE.SUBMIT || iouType === CONST.IOU.TYPE.REQUEST) {
   223	                    IOU.requestMoney(
   224	                        report,
   225	                        backendAmount,
   226	                        currency,
   227	                        transaction?.created ?? '',
   228	                        CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT,
   229	                        currentUserPersonalDetails.login,
   230	                        currentUserPersonalDetails.accountID,
   231	                        participants[0],
   232	                        '',
   233	                        {},
   234	                    );
   235	                    return;
   236	                }
   237	                if (iouType === CONST.IOU.TYPE.TRACK) {
   238	                    IOU.trackExpense(
   239	                        report,
   240	                        backendAmount,
   241	                        currency ?? 'USD',
   242	                        transaction?.created ?? '',
   243	                        CONST.TRANSACTION.PARTIAL_TRANSACTION_MERCHANT,
   244	                        currentUserPersonalDetails.login,
   245	                        currentUserPersonalDetails.accountID,
   246	                        participants[0],
   247	                        '',
   248	                    );
   249	                    return;
   250	                }
   251	            }
   252	            IOU.setMoneyRequestParticipantsFromReport(transactionID, report);
   253	            if (isSplitBill && !report.isOwnPolicyExpenseChat && report.participants) {
   254	                const participantAccountIDs = Object.keys(report.participants).map((accountID) => Number(accountID));
   255	                IOU.setSplitShares(transaction, amountInSmallestCurrencyUnits, currency || CONST.CURRENCY.USD, participantAccountIDs);
   256	            }
   257	            navigateToConfirmationPage();
   258	            return;
   259	        }
   260	
   261	        // If there was no reportID, then that means the user started this flow from the global + menu
   262	        // and an optimistic reportID was generated. In that case, the next step is to select the participants for this expense.
   263	        navigateToParticipantPage();
   264	    };
   265	
   266	    const saveAmountAndCurrency = ({amount, paymentMethod}: AmountParams) => {
   267	        const newAmount = CurrencyUtils.convertToBackendAmount(Number.parseFloat(amount));
   268	
   269	        // Edits to the amount from the splits page should reset the split shares.
   270	        if (transaction?.splitShares) {
   271	            IOU.resetSplitShares(transaction, newAmount, currency);
   272	        }
   273	
   274	        if (!isEditing) {
   275	            navigateToNextPage({amount, paymentMethod});
   276	            return;
   277	        }
   278	
   279	        // If the value hasn't changed, don't request to save changes on the server and just close the modal
   280	        const transactionCurrency = TransactionUtils.getCurrency(currentTransaction);
   281	        if (newAmount === TransactionUtils.getAmount(currentTransaction) && currency === transactionCurrency) {
   282	            navigateBack();
   283	            return;
   284	        }
   285	
   286	        // If currency has changed, then we get the default tax rate based on currency, otherwise we use the current tax rate selected in transaction, if we have it.
   287	        const transactionTaxCode = ReportUtils.getTransactionDetails(currentTransaction)?.taxCode;
   288	        const defaultTaxCode = TransactionUtils.getDefaultTaxCode(policy, currentTransaction, currency) ?? '';
   289	        const taxCode = (currency !== transactionCurrency ? defaultTaxCode : transactionTaxCode) ?? defaultTaxCode;
   290	        const taxPercentage = TransactionUtils.getTaxValue(policy, currentTransaction, taxCode) ?? '';
   291	        const taxAmount = CurrencyUtils.convertToBackendAmount(TransactionUtils.calculateTaxAmount(taxPercentage, newAmount, currency ?? CONST.CURRENCY.USD));
   292	
   293	        if (isSplitBill) {
   294	            IOU.setDraftSplitTransaction(transactionID, {amount: newAmount, currency, taxCode, taxAmount});
   295	            navigateBack();
   296	            return;
   297	        }
   298	
   299	        IOU.updateMoneyRequestAmountAndCurrency({transactionID, transactionThreadReportID: reportID, currency, amount: newAmount, taxAmount, policy, taxCode});
   300	        navigateBack();
   301	    };
